/**
 * Available slots are instants generated by the backend in BOOKING_TIME_ZONE
 * (default Asia/Ho_Chi_Minh, see beauty-booking-api-main/src/common/utils/booking-datetime.ts).
 * mappers/booking.ts already reads appointment wall clocks as +07:00, so slot
 * labels use the same zone instead of the device timezone.
 */
export const BOOKING_ZONE = 'Asia/Ho_Chi_Minh';

function parts(value: string, zone: string) {
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return null;
  try {
    const formatted = new Intl.DateTimeFormat('en-GB', {
      timeZone: zone, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short', hourCycle: 'h23',
    }).formatToParts(date);
    const get = (type: string) => formatted.find((part) => part.type === type)?.value ?? '';
    return { year: get('year'), month: get('month'), day: get('day'), hour: get('hour'), minute: get('minute'), weekday: get('weekday') };
  } catch {
    return null;
  }
}

/** HH:mm in the booking zone; never falls back to the device timezone. */
export function slotClock(value: string, zone = BOOKING_ZONE): string {
  const p = parts(value, zone);
  return p ? `${p.hour}:${p.minute}` : '--:--';
}

/** Hour (0–23) in the booking zone, used to group morning/afternoon/evening. */
export function slotHour(value: string, zone = BOOKING_ZONE): number {
  const p = parts(value, zone);
  return p ? Number(p.hour) : NaN;
}

const WEEKDAYS: Record<string, string> = { Mon: 'Thứ Hai', Tue: 'Thứ Ba', Wed: 'Thứ Tư', Thu: 'Thứ Năm', Fri: 'Thứ Sáu', Sat: 'Thứ Bảy', Sun: 'Chủ Nhật' };

/** e.g. “Thứ Bảy, 12/10/2026” in the booking zone. */
export function slotDate(value: string, zone = BOOKING_ZONE): string {
  const p = parts(value, zone);
  return p ? `${WEEKDAYS[p.weekday] ?? p.weekday}, ${p.day}/${p.month}/${p.year}` : '';
}
